import csv
from pathlib import Path
from openpyxl import load_workbook
idx='/app/input_files/sec_filings/Source_Index.csv'
with open(idx,newline='') as f: known={r['Source_ID'] for r in csv.DictReader(f)}
uses={}
for p in Path('/app/input_files').rglob('*.csv'):
 try:
  with open(p,newline='') as f:
   rows=list(csv.DictReader(f))
 except Exception: continue
 for i,r in enumerate(rows,2):
  for k,v in r.items():
   if k and ('source' in k.lower()) and v:
    uses.setdefault(v,[]).append(f'{p}:line {i} ({k})')
for p in Path('/app/input_files').rglob('*.xlsx'):
 wb=load_workbook(p,data_only=False,read_only=False)
 for ws in wb.worksheets:
  headers={c.column:c.value for c in ws[1] if c.value}
  sourcecols={col for col,h in headers.items() if 'source' in str(h).lower()}
  for row in range(2,ws.max_row+1):
   for col in sourcecols:
    v=ws.cell(row,col).value
    if v: uses.setdefault(str(v),[]).append(f'{p}:{ws.title}!{ws.cell(row,col).coordinate}')
